contract InvMutTest {
    C c;
    CoolerFactory factory;

    constructor(C _c) {
        c = _c;
        factory = c.factory();
    }

    // params: amount, interest, loanToCollateral, duration
    // We will have this contract act as the requester (owner) and then another address (this contract) will clear the request by calling clearRequest.
    // Because in the testing harness msg.sender for calls to c will be this contract, we simulate a lender by using call from this contract as well.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0, "no zero divis");

        // 1) create a request as msg.sender (this contract) by calling requestLoan
        // we must ensure collateral transfer will succeed: collateral is an ERC20; we cannot mint here, but the test framework deploys fresh C whose collateral token may be arbitrary.
        // To make the test robust we avoid calls that transfer tokens; instead we only interact with request/clearRequest invariants that do not rely on successful token transfers when failing would revert.
        // However requestLoan calls safeTransferFrom which will likely revert if token allowances/balances absent; so instead we will create a Request struct directly via low-level clone args are fixed at deploy, but we cannot write c.requests.
        // Alternate plan: rely on clearRequest reverting if not active; but we need a general rule that when clearRequest succeeds it sets loans[loanID].lender == msg.sender and requests[reqID].active == false.
        // To ensure clearRequest is callable without token transfers, we use try/catch to detect revert and assert relation between revert flag and post-conditions: if clearRequest did not revert then the created loan's lender equals msg.sender and request inactive.

        // We must call clearRequest with some reqID; choose 0. Attempt call and record whether it reverted.
        bool clearedReverted;
        uint256 loanID;
        try c.clearRequest{value: 0}(0, false, false) returns (uint256 lid) {
            clearedReverted = false;
            loanID = lid;
        } catch {
            clearedReverted = true;
            loanID = type(uint256).max;
        }

        // Read observable values after call
        bool reqActive;
        C.Request memory req;
        C.Loan memory loan;
        // Safe reads: getRequest may revert if out-of-bounds; wrap in try/catch
        bool gotReq;
        try c.getRequest(0) returns (C.Request memory r) {
            req = r;
            reqActive = req.active;
            gotReq = true;
        } catch {
            reqActive = false;
            gotReq = false;
        }

        bool gotLoan;
        if (!clearedReverted) {
            // if clear succeeded, loanID is valid; try to read it
            try c.getLoan(loanID) returns (C.Loan memory l) {
                loan = l;
                gotLoan = true;
            } catch {
                gotLoan = false;
            }
        } else {
            gotLoan = false;
        }

        // General rule: If clearRequest did NOT revert then the created loan's lender must equal address(this)
        // and the original request (id 0) must now be inactive. If clearRequest reverted, we cannot assert loan properties.
        assert((clearedReverted) || (gotLoan && gotReq && loan.lender == address(this) && reqActive == false));
    }

    receive() external payable {}
}

