contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: prepare a request and then call clearRequest; caller (this contract) will be msg.sender for requests
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, bool repayDirect_, bool isCallback_) public payable {
        require(true);

        // Make a request from this contract (msg.sender == this)
        // record requests length before
        uint256 reqLenBefore = c.requests.length;

        // call requestLoan to create a request; this will transfer collateral from this contract to c, so ensure we have allowance/balance is not possible here — but the call may revert in which case we observe revert and assert accordingly.
        bool reqReverted;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
            reqReverted = false;
        } catch {
            reqReverted = true;
        }

        // If requestLoan reverted, then nothing changed about requests length; ensure that by asserting requests.length == reqLenBefore in that case
        if (reqReverted) {
            assert(c.requests.length == reqLenBefore);
            return;
        }

        // Now there is at least one request. We target the latest request id
        uint256 reqID = reqLenBefore;

        // Ensure the request is active (it should be active after creation)
        C.Request memory createdReq = c.getRequest(reqID);
        // if not active, bail out by asserting that clearRequest would revert (we won't call it) — but to satisfy the single assert rule we will later assert a single global property

        // Record loans length before attempting clearRequest
        uint256 loansBefore = c.loans.length;

        // Attempt to call clearRequest from this contract (msg.sender == this). Use try/catch to observe revert.
        bool clearedReverted;
        uint256 newLoanID = type(uint256).max;
        try c.clearRequest(reqID, repayDirect_, isCallback_) returns (uint256 loanID) {
            clearedReverted = false;
            newLoanID = loanID;
        } catch {
            clearedReverted = true;
        }

        // Final observations
        uint256 loansAfter = c.loans.length;

        // Single general assert combining both outcomes:
        // If clearRequest reverted then either the request was not active or caller was rejected (e.g., callback check) — in that case loans length must be unchanged.
        // If clearRequest succeeded then loans.length increased by exactly 1 and the created loan's embedded request.active is false.
        assert(
            clearedReverted
                ? (loansAfter == loansBefore)
                : (
                    loansAfter == loansBefore + 1
                    && newLoanID == loansBefore
                    && c.getLoan(newLoanID).request.active == false
                )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We create a request from this contract, then attempt to clear it.
    // Parameters: values for requestLoan and clearRequest.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, bool repayDirect_, bool isCallback_) public payable {
        require(true);

        // Record number of requests by calling requests.length via a view accessor: use getRequest in a loop until it reverts to find length.
        // But simpler: we can't read requests.length directly (it's a public array with autogenerated getter that takes an index),
        // so we'll infer the next request id by trying increasing indices until a call reverts. However, view call reverts are expensive; instead,
        // we can call requestLoan and on success we know the created reqID is the previous requests length, which we can't read directly beforehand.

        // Try to create a request. Observe whether it reverts.
        bool reqReverted;
        uint256 createdReqID = type(uint256).max;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 reqID) {
            reqReverted = false;
            createdReqID = reqID;
        } catch {
            reqReverted = true;
        }

        // If request creation reverted, then no request was added and clearRequest cannot succeed for that reqID; so the property reduces to: loans.length unchanged when clearRequest reverts.
        // We need loans.length before attempting clearRequest. We cannot read loans.length directly (autogenerated getter is getLoan(index)), so infer loans length by probing until getLoan(index) reverts.
        // Implement a small bounded probe to find current loans length: search up to 16 entries (sufficient for property checking); if beyond bound, treat as unknown and abort via require(false).

        uint256 loansBefore = probeLoansLength();
        // If request creation reverted, we assert that attempting to clear that non-existent request will revert and loans length unchanged.
        if (reqReverted) {
            bool clearedReverted;
            try c.clearRequest(0, repayDirect_, isCallback_) returns (uint256) {
                clearedReverted = false;
            } catch {
                clearedReverted = true;
            }
            // single assert: if clearRequest reverted then loans length unchanged (we observed loansBefore and no state-changing call succeeded), else if it didn't revert we require loans increased by 1.
            // But we didn't create a request, so if clearRequest succeeded that would be surprising; nonetheless express the general property.
            uint256 loansAfter = probeLoansLength();
            assert(clearedReverted ? loansAfter == loansBefore : loansAfter == loansBefore + 1);
            return;
        }

        // If request created, createdReqID holds its id. Now attempt clearRequest on that id and observe whether it reverts and whether loans length increases by 1.
        bool clearedReverted;
        uint256 newLoanID = type(uint256).max;
        try c.clearRequest(createdReqID, repayDirect_, isCallback_) returns (uint256 loanID) {
            clearedReverted = false;
            newLoanID = loanID;
        } catch {
            clearedReverted = true;
        }

        uint256 loansAfter = probeLoansLength();

        // Single general assert as required:
        // If clearRequest reverted then loans length unchanged; otherwise loans length increased by exactly 1 and returned loanID equals previous loansBefore and the created loan's request.active is false.
        assert(
            clearedReverted
                ? loansAfter == loansBefore
                : (
                    loansAfter == loansBefore + 1
                    && newLoanID == loansBefore
                    && c.getLoan(newLoanID).request.active == false
                )
        );
    }

    // Helper: probe loans length by calling getLoan(i) until it reverts; bounded to 64 to ensure termination.
    function probeLoansLength() internal view returns (uint256) {
        uint256 i = 0;
        for (; i < 64; i++) {
            // getLoan(i) is public view returning (Loan). If it reverts for out-of-bounds, we stop.
            // We use try/catch on external call via address(c).call to avoid ABI decoding issues in view context.
            (bool ok, ) = address(c).staticcall(abi.encodeWithSignature("getLoan(uint256)", i));
            if (!ok) return i;
        }
        // If more than bound, abort the test since we cannot reliably probe further.
        revert("loans length exceeds probe bound");
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We try to create a request from this contract; parameters choose request fields.
    // We assert: if requestLoan succeeds (does not revert) it returns some reqID and the created request is active.
    // If it reverts then no request was created. Because we cannot directly observe token balances of arbitrary ERC20 except via the ERC20 public balanceOf,
    // we will assert that when requestLoan succeeds, the request at that id is active. If it reverts, the previous requests count is unchanged.
    // To keep calls flat: top-level try/catch for requestLoan, then probe existing requests length before and after by sequentially calling getRequest(i) at top level.

    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(true);

        // Probe requests length before by calling getRequest sequentially until one call reverts. Bounded to 64.
        uint256 before = 0;
        for (; before < 64; before++) {
            try c.getRequest(before) returns (C.Request memory) {
                // exists, continue
            } catch {
                break;
            }
        }

        bool reqReverted;
        uint256 createdReqID = type(uint256).max;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 reqID) {
            reqReverted = false;
            createdReqID = reqID;
        } catch {
            reqReverted = true;
        }

        // Probe requests length after
        uint256 after = 0;
        for (; after < 64; after++) {
            try c.getRequest(after) returns (C.Request memory) {
                // exists
            } catch {
                break;
            }
        }

        // Single general assert: if requestLoan reverted then requests length unchanged; otherwise requests length increased by exactly 1 and the new request is active and matches returned id.
        assert(
            reqReverted
                ? after == before
                : (
                    after == before + 1
                    && createdReqID == before
                    && c.getRequest(createdReqID).active == true
                )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We attempt to call requestLoan; we observe the number of existing requests by probing getRequest(i)
    // until it reverts (bounded loop). Then call requestLoan in a try/catch and re-probe. The assert encodes
    // that either the call reverted and the count is unchanged, or it succeeded, increased count by 1,
    // and the returned reqID indexes an active request.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(true);

        uint256 beforeCount = 0;
        // probe up to 128 requests to find current length
        for (; beforeCount < 128; beforeCount++) {
            try c.getRequest(beforeCount) returns (C.Request memory) {
                // exists, continue
            } catch {
                break;
            }
        }

        bool didRevert;
        uint256 returnedID = type(uint256).max;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 reqID) {
            didRevert = false;
            returnedID = reqID;
        } catch {
            didRevert = true;
        }

        uint256 afterCount = 0;
        for (; afterCount < 128; afterCount++) {
            try c.getRequest(afterCount) returns (C.Request memory) {
                // exists
            } catch {
                break;
            }
        }

        // Final assertion: either reverted and counts equal, or succeeded and count increased by 1,
        // returnedID equals previous count (new index), and that request is active.
        assert(
            didRevert
                ? afterCount == beforeCount
                : (
                    afterCount == beforeCount + 1
                    && returnedID == beforeCount
                    && c.getRequest(returnedID).active == true
                )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We keep parameters bounded to avoid huge loops and ensure collateral transfer can be computed.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        // Bound parameters to reasonable sizes so probing the array is feasible in the single tx.
        require(loanToCollateral_ != 0 && loanToCollateral_ <= 1e30);
        require(duration_ <= 365 days * 10);

        // Discover current requests length by probing until getRequest(i) reverts.
        uint256 beforeCount = 0;
        for (; beforeCount < 64; beforeCount++) {
            try c.getRequest(beforeCount) returns (C.Request memory) {
                // exists
            } catch {
                break;
            }
        }

        bool didRevert;
        uint256 returnedID = type(uint256).max;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 reqID) {
            didRevert = false;
            returnedID = reqID;
        } catch {
            didRevert = true;
        }

        // Probe new length
        uint256 afterCount = 0;
        for (; afterCount < 64; afterCount++) {
            try c.getRequest(afterCount) returns (C.Request memory) {
                // exists
            } catch {
                break;
            }
        }

        // Assert: either call reverted and length unchanged, or succeeded and length increased by 1,
        // returnedID equals previous length, and the appended request is active.
        assert(
            didRevert
                ? afterCount == beforeCount
                : (
                    afterCount == beforeCount + 1
                    && returnedID == beforeCount
                    && c.getRequest(returnedID).active == true
                )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: amount_, interest_, loanToCollateral_, duration_, caller provides collateral by being msg.sender of the test
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(address(this).balance >= 0, true);

        // Read pre-state: contract collateral token and its decimals and C's balance of that token cannot be read directly.
        // Instead, observe address(c).balance only for Ether; collateral is ERC20 so we cannot read token balances of c except via public ERC20.balanceOf.
        // We will use the collateral() getter to obtain the ERC20 token, and then query balanceOf(address(c)).

        ERC20 coll = c.collateral();

        uint256 beforeCollBal = coll.balanceOf(address(c));

        // Approve and mint tokens to this contract if token supports minting? We cannot mint arbitrary ERC20. However test harness provides arbitrary inputs and initial state — but the checker deploys fresh c; collateral token is provided in constructor of clone, may be arbitrary. To avoid needing token setup, we use a precondition: require that this contract already has enough collateral tokens to transfer the needed amount.
        uint256 needed = c.collateralFor(amount_, loanToCollateral_);

        require(coll.balanceOf(address(this)) >= needed, "test-precondition: insufficient collateral for caller");
        // approve C to pull tokens
        coll.approve(address(c), needed);

        bool reverted;
        uint256 reqID;
        // perform the state-changing call as a top-level statement
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 id) {
            reverted = false;
            reqID = id;
        } catch {
            reverted = true;
        }

        // After call: if it didn't revert, the request at reqID must be active and match inputs and contract collateral increased by needed.
        if (!reverted) {
            C.Request memory r = c.getRequest(reqID);
            uint256 afterCollBal = coll.balanceOf(address(c));

            // assert the general invariant
            assert(
                // fields equal to inputs
                r.amount == amount_
                && r.interest == interest_
                && r.loanToCollateral == loanToCollateral_
                && r.duration == duration_
                && r.active == true
                // collateral balance increased by exactly needed
                && afterCollBal >= beforeCollBal
                && afterCollBal - beforeCollBal == needed
            );
        } else {
            // If reverted, we assert nothing about state but still must reach a general rule: here assert that if reverted then the request array length did not increase at some index equal to a returned reqID — but we cannot reference reqID.
            // So when reverted we assert a tautology that depends on observed reverted flag to keep a single assert at end. To satisfy the requirement that assert is general (over params and observed values), we assert reverted || true which is useless; instead we assert that reverted implies the contract's requests remain unchanged in length compared to reading before.
            // To do that we needed before length. Move reading before.
            revert("internal: unreachable");
        }
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // parameters: amount_, interest_, loanToCollateral_, duration_
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        // Observe collateral token and this contract's balance of it before the call
        ERC20 coll = c.collateral();
        uint256 beforeCollBalC = coll.balanceOf(address(c));
        uint256 beforeRequests = c.requestsLength();

        // compute required collateral to be transferred by requestLoan
        uint256 needed = c.collateralFor(amount_, loanToCollateral_);

        // require the test contract has enough tokens to allow the transfer; otherwise the call would revert for lack of funds
        require(coll.balanceOf(address(this)) >= needed, "precondition: caller lacks collateral");

        // approve c to transfer needed tokens
        coll.approve(address(c), needed);

        bool reverted;
        uint256 reqID;

        // perform the state-changing call as a top-level statement and catch revert
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 id) {
            reverted = false;
            reqID = id;
        } catch {
            reverted = true;
            reqID = type(uint256).max; // sentinel
        }

        // After call: assert the general rule using a single assert
        // If call did not revert then:
        //  - requests.length increased by 1 (new index equals returned reqID)
        //  - the Request at reqID has fields equal to the inputs and active==true
        //  - c's collateral token balance increased exactly by needed
        // If call reverted then nothing specific about those must hold; we encode as: reverted OR (all the properties)
        if (!reverted) {
            C.Request memory r = c.getRequest(reqID);
            uint256 afterCollBalC = coll.balanceOf(address(c));
            uint256 afterRequests = c.requestsLength();

            assert(
                // the call did not revert and the request index is the new last index
                !reverted
                && reqID + 1 == afterRequests
                && afterRequests == beforeRequests + 1
                // request fields match inputs
                && r.amount == amount_
                && r.interest == interest_
                && r.loanToCollateral == loanToCollateral_
                && r.duration == duration_
                && r.active == true
                // collateral balance increased by exactly needed
                && afterCollBalC >= beforeCollBalC
                && afterCollBalC - beforeCollBalC == needed
            );
        } else {
            // If reverted, still need to reach a single assert; assert a property that must hold when reverted: the requests length did not increase
            uint256 afterRequestsRevert = c.requestsLength();
            assert(reverted && afterRequestsRevert == beforeRequests);
        }
    }

    // Expose helper view to read requests.length via public surface only once (calls allowed)
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount_, interest_, loanToCollateral_, duration_
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        ERC20 coll = c.collateral();

        // Observe before state via public surface
        uint256 beforeCollBalC = coll.balanceOf(address(c));
        uint256 beforeRequestsLen = c.getRequest(0).amount; // cheap read attempt to ensure getRequest exists; will not be used when no requests
        // We cannot read requests.length (no getter). Instead, infer length by trying to read getRequest incrementally until it reverts is not allowed here.
        // Workaround: use try/catch around requestLoan and on success check that the returned reqID indexes a Request with expected fields and that collateral delta equals collateralFor.

        uint256 needed = c.collateralFor(amount_, loanToCollateral_);

        // ensure this contract has enough collateral to allow the transfer; otherwise the call will revert due to insufficient token balance
        require(coll.balanceOf(address(this)) >= needed, "precondition: caller lacks collateral");

        // approve C to pull collateral
        coll.approve(address(c), needed);

        bool reverted;
        uint256 reqID;

        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 id) {
            reverted = false;
            reqID = id;
        } catch {
            reverted = true;
            reqID = type(uint256).max;
        }

        uint256 afterCollBalC = coll.balanceOf(address(c));

        if (!reverted) {
            C.Request memory r = c.getRequest(reqID);
            // When successful, the Request at reqID must match inputs and be active, and C's collateral balance increases exactly by needed.
            assert(
                r.amount == amount_
                && r.interest == interest_
                && r.loanToCollateral == loanToCollateral_
                && r.duration == duration_
                && r.active == true
                && afterCollBalC >= beforeCollBalC
                && afterCollBalC - beforeCollBalC == needed
            );
        } else {
            // If reverted, we assert that C's collateral balance did not increase (no transfer happened).
            assert(reverted && afterCollBalC == beforeCollBalC);
        }
    }

    receive() external payable { }
}

