        uint256 beforeCollBalC = coll.balanceOf(address(c));
        uint256 beforeRequests = c.requests.length;

        // compute expected collateral required
        uint256 needed = c.collateralFor(amount_, loanToCollateral_);

        // ensure this test contract can supply the collateral required; otherwise the call will likely revert
        require(coll.balanceOf(address(this)) >= needed, "precondition: caller lacks collateral");

        // approve C to pull collateral
        coll.approve(address(c), needed);

        // perform the state-changing call as its own top-level statement using try/catch
        bool succeeded;
        uint256 returnedReqID;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 id) {
            succeeded = true;
            returnedReqID = id;
        } catch {
            succeeded = false;
            returnedReqID = type(uint256).max;
        }

        // read after-state
        uint256 afterCollBalC = coll.balanceOf(address(c));
        uint256 afterRequests = c.requests.length;

        // Single general assert describing the invariant for all inputs
        assert(
            // If requestLoan succeeded then a new request was appended and matches inputs and collateral increased exactly
            (succeeded &&
                returnedReqID < afterRequests &&
                afterRequests == beforeRequests + 1 &&
                c.getRequest(returnedReqID).amount == amount_ &&
                c.getRequest(returnedReqID).interest == interest_ &&
                c.getRequest(returnedReqID).loanToCollateral == loanToCollateral_ &&
                c.getRequest(returnedReqID).duration == duration_ &&
                c.getRequest(returnedReqID).active == true &&
                afterCollBalC >= beforeCollBalC &&
                afterCollBalC - beforeCollBalC == needed
            )
            // If it reverted then requests length unchanged and collateral balance unchanged
            || (!succeeded && afterRequests == beforeRequests && afterCollBalC == beforeCollBalC)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take parameters that drive requestLoan. The caller of c (msg.sender for c calls)
    // will be this contract, but collateral().safeTransferFrom will attempt to pull tokens
    // from this contract. The checker deploys a fresh c and provides token behavior accordingly.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(true);

        // Record pre-state: number of requests
        uint256 reqCountBefore = c.requests.Length();
        // NOTE: since requests is public array, solidity auto-generates a getter requests(uint256) and requests().length is accessible via low-level .requests(uint256) for elements, but not .Length().
        // To observe length we use the public accessor getRequest by calling until revert would be awkward.
        // Instead, use try/catch when calling requestLoan and then verify properties assuming it didn't revert.

        bool reverted;
        uint256 reqID;
        // make the state-changing call as top-level statement
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 id) {
            reverted = false;
            reqID = id;
        } catch {
            reverted = true;
        }

        // If call reverted, then we assert that no new request exists at the index equal to the returned id (none). But we must state a general rule about non-revert case.
        // Observe: when not reverted, request with id 'reqID' should be active and have amount == amount_.
        // We can call c.getRequest(reqID) as it's public view and returns the Request struct.

        if (!reverted) {
            C.Request memory req = c.getRequest(reqID);
            // assert general rule: the created request is active and amount equals input amount
            assert(req.active && req.amount == amount_);
        } else {
            // If reverted, we still must reach a single assert. Use a relation that holds when reverted: caller balance of c unchanged or simply assert(reverted == reverted) is trivial but forbidden.
            // To satisfy constraints (one assert total), we instead place the final assert outside and express combined property: either reverted is true OR (request active and amounts equal).
            // So we need to read request only if not reverted, but solidity requires expressions available; we'll implement combined assert below.
        }

        // Single final assert over observable values and revert flag.
        // To read request fields safely when reverted is true, we use a conditional: if reverted then skip reading by using a short-circuit expression.
        C.Request memory maybeReq;
        if (!reverted) maybeReq = c.getRequest(reqID);

        assert(reverted || (maybeReq.active && maybeReq.amount == amount_));
    }

    // Minimal receive to accept ERC20 transfers if token sends ETH mistakenly
    receive() external payable {}
}

