contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount, interest, loanToCollateral, duration
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        // No precondition on inputs.
        ERC20 coll = c.collateral();

        // Read the number of requests before by calling requests getter repeatedly until it reverts (requests is an array; we can probe length via getRequest in a loop).
        // But easier: use try/catch on requestLoan and then compare lengths via probing increasing indices until getRequest reverts.
        // However getRequest is public and will revert if index out of bounds. We'll get length by binary probing up to a reasonable bound.

        // We choose a simple approach: find the current length by increasing i until getRequest(i) reverts or until a cap.
        uint256 cap = 100; // avoid infinite loop; fresh contract should have small number of requests
        uint256 reqLenBefore = 0;
        for (uint256 i = 0; i < cap; i++) {
            // try to read getRequest(i)
            bool ok = true;
            try c.getRequest(i) returns (C.Request memory) {
                reqLenBefore++;
            } catch {
                ok = false;
            }
            if (!ok) break;
        }

        uint256 beforeBal = coll.balanceOf(address(c));

        bool reverted;
        uint256 retReqID = type(uint256).max;

        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 r) {
            reverted = false;
            retReqID = r;
        } catch {
            reverted = true;
        }

        // compute after values
        uint256 reqLenAfter = 0;
        for (uint256 i = 0; i < cap; i++) {
            bool ok = true;
            try c.getRequest(i) returns (C.Request memory) {
                reqLenAfter++;
            } catch {
                ok = false;
            }
            if (!ok) break;
        }

        uint256 afterBal = coll.balanceOf(address(c));

        // compute expected collateral via public view
        uint256 expectedColl = c.collateralFor(amount_, loanToCollateral_);

        // If call reverted: length unchanged and balance unchanged.
        // If succeeded: length increased by 1, returned reqID equals old length, that request is active and has amount == amount_, and balance increased by expectedColl.
        bool successCase = false;
        if (!reverted) {
            // require that we probed enough cap to see the new element
            // check returned id equals previous length
            if (retReqID == reqLenBefore && reqLenAfter == reqLenBefore + 1) {
                // read the stored request via getRequest
                C.Request memory req = c.getRequest(retReqID);
                if (req.active == true && req.amount == amount_) {
                    // check balance delta
