contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: request parameters and flags controlling clearRequest
    function run(
        uint256 reqAmount,
        uint256 reqInterest,
        uint256 reqLoanToCollateral,
        uint256 reqDuration,
        bool repayDirect,
        bool isCallback
    ) public payable {
        require(true);

        // Step 1: create a request by calling requestLoan from this contract
        // This will pull collateral from msg.sender (this contract). To satisfy that, we must ensure
        // collateral token approves and balances exist. However we cannot mint tokens here.
        // Instead, we follow a different approach: call requestLoan only if collateral transfer will succeed
        // The safe path for a property test: attempt clearRequest by first pushing a request via storage
        // But we cannot write c.requests directly. So instead, we use the public API: create a request by
        // calling requestLoan and accept that it may revert; we capture revert.

        bool reqReverted;
        uint256 reqID;
        try c.requestLoan(reqAmount, reqInterest, reqLoanToCollateral, reqDuration) {
            reqReverted = false;
            // if succeeded, the new request has id (requests.length-1). We can read it via getRequest with index 0..large
            // But we don't know index; requestLoan returns reqID so we captured it.
        } catch {
            reqReverted = true;
        }

        // If request creation reverted, then we cannot proceed to clear; in that case we assert that clear would also revert
        bool clearReverted;
        uint256 loanID;
        if (!reqReverted) {
            // attempt to call clearRequest(reqID, repayDirect, isCallback)
            try c.clearRequest(reqID, repayDirect, isCallback) returns (uint256 id) {
                clearReverted = false;
                loanID = id;
            } catch {
                clearReverted = true;
            }

            // If clearRequest did not revert then the created loan (index loanID) must have lender == msg.sender (this contract)
            // and the request must be inactive.
            bool lenderMatches;
            bool requestInactive;

            if (!clearReverted) {
                C.Loan memory ln = c.getLoan(loanID);
                lenderMatches = ln.lender == address(this);

                C.Request memory rq = c.getRequest(reqID);
                requestInactive = rq.active == false;
            } else {
                // if clear reverted, we cannot observe loan; set both false
                lenderMatches = false;
                requestInactive = false;
            }

            assert(clearReverted || (lenderMatches && requestInactive));
        } else {
            // If initial request creation reverted, then clearRequest cannot succeed because there's no request to clear.
            // We attempt clearRequest and assert it reverts.
            try c.clearRequest(0, repayDirect, isCallback) returns (uint256 id) {
                clearReverted = false;
                loanID = id;
            } catch {
                clearReverted = true;
            }

            assert(clearReverted);
        }
    }

    receive() external payable {}
}

