        bool reqReverted;
        uint256 reqID;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 id) {
            reqReverted = false;
            reqID = id;
        } catch {
            reqReverted = true;
        }

        if (reqReverted) {
            // if request reverted, assert that it did revert
            assert(reqReverted == true);
            return;
        }

        // Observe the stored request via view
        C.Request memory rq = c.getRequest(reqID);
        uint256 reqAmount = rq.amount;

        // Ensure this contract has enough debt tokens to act as lender; otherwise vacuously observe that
        if (debt.balanceOf(address(this)) < reqAmount) {
            assert(debt.balanceOf(address(this)) < reqAmount);
            return;
        }

        // Record balances before clearRequest
        uint256 beforeOwnerDebt = debt.balanceOf(address(c.owner()));
        uint256 beforeThisDebt = debt.balanceOf(address(this));

        // Attempt clearRequest as lender (this contract) — top-level call
        bool clearReverted;
        uint256 loanID;
        try c.clearRequest(reqID, true, false) returns (uint256 id) {
            clearReverted = false;
            loanID = id;
        } catch {
            clearReverted = true;
        }

        if (clearReverted) {
            // if clearRequest reverted, assert that it did revert
            assert(clearReverted == true);
            return;
        }

        // On success, observable properties must hold
        C.Loan memory loan = c.getLoan(loanID);
        bool lenderIsThis = (loan.lender == address(this));

        uint256 afterOwnerDebt = debt.balanceOf(address(c.owner()));
        uint256 afterThisDebt = debt.balanceOf(address(this));

        bool ownerIncreased = afterOwnerDebt >= beforeOwnerDebt + reqAmount;
        bool thisDecreased = beforeThisDebt >= afterThisDebt + reqAmount;

        // General rule: loan.lender == msg.sender and either owner's balance increased by at least reqAmount or this contract's balance decreased by at least reqAmount
        assert(lenderIsThis && (ownerIncreased || thisDecreased));
    }

    receive() external payable {}
}

