contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot read requests.length directly (no autogenerated length getter), so we determine length by probing
    // indices starting from 0 until getRequest(i) reverts. This is used only for observation and must be done before
    // and after the tested call. The single public function contains all logic.
    function run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public payable {
        // avoid division by zero in collateralFor which may be used during request processing
        require(loanToCollateral != 0, "loanToCollateral!=0");

        // helper to discover current requests length by calling getRequest until it reverts
        uint256 beforeLen = 0;
        while (true) {
            // try to call getRequest(beforeLen). If it reverts, we've found the length.
            try c.getRequest(beforeLen) returns (C.Request memory) {
                beforeLen++;
                // continue probing
            } catch {
                break;
            }
        }

        bool reverted;
        try c.requestLoan(amount, interest, loanToCollateral, duration) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // compute length after
        uint256 afterLen = 0;
        while (true) {
            try c.getRequest(afterLen) returns (C.Request memory) {
                afterLen++;
            } catch {
                break;
            }
        }

        // If call reverted, length must be unchanged. If it did not revert, length must have increased by exactly 1
        // and the newly inserted request at index `beforeLen` must be active and have amount == amount param.
        if (reverted) {
            assert(afterLen == beforeLen);
        } else {
            assert(afterLen == beforeLen + 1);
            (uint256 amt, uint256 intr, uint256 l2c, uint256 dur, bool active) = c.getRequest(beforeLen);
            assert(active && amt == amount);
        }
    }

    receive() external payable {}
}

